/// <summary>
/// Extension of SalesInvoiceJournalPost for DSD calculations
/// </summary>
[ExtensionOf(classStr(SalesInvoiceJournalPost))]
internal final class AVARUMSalesInvoiceJournalPostCls_Extension
{
}

Method.Source:
/// <summary>
/// Calculate an add DSD fee
/// </summary>
protected void afterLinePost()
{
    next afterLinePost();
    Common common=this.journalLine();
    if (common is CustInvoiceTrans
        && !this.isProforma())
    {
        CustInvoiceTrans locCustInvoiceTrans=common;
        AVARUMDSDCalculationManager::calcPackingCharges(locCustInvoiceTrans.ItemId,  locCustInvoiceTrans.inventDim().configId, locCustInvoiceTrans, 1.0);
    }
}
